fn first_space(s, i) {
  if len(s) <= i { -1 }
  else if s[i] == " " { i }
  else { first_space(s, i + 1) }
}

fn extend(xs, ys, i) {
  if len(ys) <= i { xs } else { extend(push(xs, ys[i]), ys, i + 1) }
